import { registerWebComponents } from '@domg-wc/common';
import { VlParagraphComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlSideNavigationLayoutComponent } from '@domg-wc/components/block/next';

// VlSideNavigationLayoutComponent laadt zelf vl-side-navigation-next.
registerWebComponents([VlSideNavigationLayoutComponent, VlTitleComponent, VlParagraphComponent]);

import { registerWebComponents } from '@domg-wc/common';
import { VlParagraphComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlStepsComponent } from '@domg-wc/components/block';
import { VlSideNavigationLayoutComponent } from '@domg-wc/components/block/next';

// VlStepsComponent laadt zelf vl-step.
registerWebComponents([VlSideNavigationLayoutComponent, VlStepsComponent, VlTitleComponent, VlParagraphComponent]);

import { registerWebComponents } from '@domg-wc/common';
import { VlParagraphComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlSideNavigationLayoutComponent } from '@domg-wc/components/block/next';

// Elke layout scant enkel de headings binnen zijn eigen heading-root-selector.
registerWebComponents([VlSideNavigationLayoutComponent, VlTitleComponent, VlParagraphComponent]);

import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent, VlParagraphComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlSideNavigationComponent, VlSideNavigationLayoutComponent } from '@domg-wc/components/block/next';
// toggleCustomTocChildren staat niet in de barrel van block/next, wel in die van de component.
import { toggleCustomTocChildren } from '@domg-wc/components/block/next/side-navigation';

registerWebComponents([
    VlSideNavigationLayoutComponent,
    VlSideNavigationComponent,
    VlLinkComponent,
    VlButtonComponent,
    VlTitleComponent,
    VlParagraphComponent,
]);

// Elke toggle-button klapt de sublijst van zijn <li> open of dicht.
document.querySelectorAll('vl-side-navigation-next .toggle-button').forEach((button) => {
    button.addEventListener('click', toggleCustomTocChildren);
});
